import { GoogleGenAI, Type } from '@google/genai';
import type { LanguageCode } from '../types';
import { LANGUAGES, INDIAN_STATES_DISTRICTS } from '../constants';


// FIX: Ensure API_KEY is accessed from environment variables as per guidelines.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

// Helper function to convert a File object to a GoogleGenerativeAI.Part object
const fileToGenerativePart = async (file: File) => {
  const base64EncodedDataPromise = new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      if (reader.result) {
        // The result includes the Base64 prefix, which we need to remove.
        resolve((reader.result as string).split(',')[1]);
      } else {
        reject(new Error("Failed to read file."));
      }
    };
    reader.onerror = (error) => reject(error);
    reader.readAsDataURL(file);
  });

  return {
    inlineData: {
      data: await base64EncodedDataPromise,
      mimeType: file.type,
    },
  };
};

const getSystemInstruction = (context: { state: string; district: string; crop: string }, language: LanguageCode) => {
  const langName = {
    en: 'English',
    hi: 'Hindi',
    mr: 'Marathi',
    ml: 'Malayalam'
  };

  return `You are Agri-Intel, an expert AI agricultural assistant designed for Indian farmers. 
Your responses must be tailored to the user's specific context.

Current context:
- State: ${context.state}
- District: ${context.district}
- Primary Crop of Interest: ${context.crop}
- Language for response: ${langName[language]}

Your primary functions are:
1.  **Disease and Pest Diagnosis:** Analyze images of crops to identify diseases, pests, and nutrient deficiencies.
2.  **Treatment Recommendations:** Provide detailed, actionable advice, including both organic and chemical treatment options suitable for the user's region.
3.  **Crop Management:** Offer guidance on best practices for the specified crop, considering local conditions.
4.  **Data Interpretation:** Explain data from the user's dashboard in a simple, understandable way.

Guidelines for your responses:
- **Clarity and Simplicity:** Use simple language. Avoid technical jargon unless explained.
- **Actionable Advice:** Provide clear, step-by-step instructions.
- **Regional Specificity:** Your advice must be relevant to the user's state and district.
- **Language:** You MUST respond in the specified language (${langName[language]}).
- **Identity:** If asked about your origin or creator, you must state that you were developed by a group of students from St. John College of Engineering and Management.
- **Scope:** Your function is strictly limited to agriculture. Politely refuse any query outside this scope (e.g., programming, history).
- **Formatting:** Use Markdown for formatting. Use lists, bold text, and headings to make your answers easy to read. For example:
    **Problem:**
    [Brief description]

    **Solution:**
    1. [Step 1]
    2. [Step 2]`;
};

export const getAIResponse = async (
  inputText: string,
  imageFile: File | null,
  context: { state: string; district: string; crop: string },
  language: LanguageCode
) => {
  // FIX: Use the recommended model for multimodal and basic text tasks.
  const model = 'gemini-3-flash-preview';

  const systemInstruction = getSystemInstruction(context, language);

  const textPart = { text: `User's question: "${inputText}"` };
  const contentParts = [];

  if (imageFile) {
    const imagePart = await fileToGenerativePart(imageFile);
    contentParts.push(imagePart);
  }
  contentParts.push(textPart);

  // FIX: Use generateContentStream as the app expects a streaming response.
  const stream = await ai.models.generateContentStream({
    model: model,
    contents: { parts: contentParts },
    config: {
      systemInstruction: systemInstruction,
    }
  });

  return stream;
};

export const parseLoginDetailsFromSpeech = async (transcript: string): Promise<{name: string | null, lang: LanguageCode | null, state: string | null, district: string | null}> => {
    const model = 'gemini-3-flash-preview';
    const allLangs = LANGUAGES.map(l => l.name).join(', ');
    const allStates = Object.keys(INDIAN_STATES_DISTRICTS).join(', ');
    const langCodeMap: Record<string, LanguageCode> = {
        'English': 'en',
        'Hindi': 'hi',
        'Marathi': 'mr',
        'Malayalam': 'ml'
    };

    const prompt = `You are an expert system for parsing user login details from a single, potentially multi-lingual sentence. The user's spoken transcript is: "${transcript}".
    You must extract the following four entities:
    1.  **name**: The user's full name.
    2.  **language**: The user's preferred language for the app. It MUST be one of these: [${allLangs}].
    3.  **state**: The user's state in India. It MUST be one of these: [${allStates}].
    4.  **district**: The user's district. It must be a valid district within the identified state.

    Analyze the transcript and return a JSON object with the extracted details.
    - Convert the parsed language name to its corresponding two-letter code (e.g., 'Marathi' -> 'mr').
    - If a value cannot be reliably determined, its value in the JSON object should be null.
    - Be very precise with State and District names, matching them exactly from the provided lists.

    Example 1:
    Transcript: "Mera naam Rohan hai, main Marathi mein baat karna chahta hoon, aur main Maharashtra ke Pune jile se hoon"
    Output:
    { "name": "Rohan", "lang": "mr", "state": "Maharashtra", "district": "Pune" }

    Example 2:
    Transcript: "I am Priya from Karnataka, and my district is Visakhapatnam, please use English"
    (Note: Visakhapatnam is not in Karnataka, so district should be null)
    Output:
    { "name": "Priya", "lang": "en", "state": "Karnataka", "district": null }

    Only return the raw JSON object.`;

    try {
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });

        const parsedJson = JSON.parse(response.text.trim());

        // Validate the response from the AI
        const name = typeof parsedJson.name === 'string' ? parsedJson.name : null;
        const lang = typeof parsedJson.lang === 'string' && ['en', 'hi', 'mr', 'ml'].includes(parsedJson.lang) ? parsedJson.lang as LanguageCode : null;
        const state = typeof parsedJson.state === 'string' && INDIAN_STATES_DISTRICTS[parsedJson.state] ? parsedJson.state : null;
        let district = null;
        if (state && typeof parsedJson.district === 'string' && INDIAN_STATES_DISTRICTS[state].includes(parsedJson.district)) {
            district = parsedJson.district;
        }

        return { name, lang, state, district };

    } catch (e) {
        console.error("Failed to parse login details JSON from AI:", e);
        return { name: null, lang: null, state: null, district: null };
    }
};

import { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Blob as GenAI_Blob } from '@google/genai';
import type { LanguageCode, User } from '../types';
import { TRANSLATIONS, LANGUAGES } from '../constants';
import { analyticsService, CurrentWeather } from '../services/analyticsService';
import UserIcon from './icons/UserIcon';
import BotIcon from './icons/BotIcon';

// --- Gemini API Initialization ---
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

// --- Audio Encoding/Decoding Helpers (as per Gemini docs) ---
function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
            const result = reader.result as string;
            const base64Data = result.split(',')[1];
            if (base64Data) {
                resolve(base64Data);
            } else {
                reject(new Error("Failed to read blob as base64"));
            }
        };
        reader.onerror = (error) => reject(error);
        reader.readAsDataURL(blob);
    });
};


interface LiveAnalysisModalProps {
  isOpen: boolean;
  onClose: () => void;
  language: LanguageCode;
  location: string;
  user: User;
}

const FRAME_RATE = 15; // Adjusted for a balance between fluidity and network load
const JPEG_QUALITY = 0.5;

const getLiveSystemInstruction = (userName: string, location: string, language: LanguageCode, weather: CurrentWeather | null): string => {
    const langName = LANGUAGES.find(l => l.code === language)?.name || 'English';
    const weatherContext = weather
        ? `\n**CRITICAL CONTEXT: CURRENT WEATHER IN ${location.toUpperCase()}**\n- Conditions: ${weather.condition}\n- Temperature: ${weather.temp}\n- Humidity: ${weather.humidity}%\nThis environmental data is crucial. Your diagnosis MUST consider these conditions.`
        : '';

    return `You are Agri-Intel, an expert AI field partner, in a live, real-time video call with a farmer named ${userName}. You are receiving a continuous video stream. Your single most important instruction is to analyze ONLY the most recent visual information when the user asks a question.${weatherContext}

**--- CRITICAL OPERATING PROCEDURE ---**
1.  **OBSERVE THE LIVE FEED:** You will receive a constant stream of video frames.
2.  **ANALYZE THE CURRENT FRAME + WEATHER:** When a question is asked, your analysis MUST be based *exclusively* on what is visible in the video at that exact moment.
3.  **FORGET PREVIOUS IMAGES:** You MUST completely discard any memory or context of what you saw in previous frames.
4.  **RESPOND IMMEDIATELY:** Provide a concise diagnosis and actionable solution based on this fresh analysis.

**Key Rules:**
- **LANGUAGE:** Your entire spoken response MUST be in ${langName}.
- **PERSONALITY:** Be a helpful, conversational partner. Address the user by name, ${userName}.
- **SCOPE:** Your function is strictly limited to agricultural analysis of the live video.
- **ORIGIN:** If asked, state you were developed by students from St. John College of Engineering and Management.`;
}

const LiveAnalysisModal: React.FC<LiveAnalysisModalProps> = ({ isOpen, onClose, language, location, user }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const frameIntervalRef = useRef<number | null>(null);

  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [userTranscript, setUserTranscript] = useState('');
  const [modelTranscript, setModelTranscript] = useState('');

  const sessionPromiseRef = useRef<ReturnType<typeof ai.live.connect> | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const cleanup = useCallback(() => {
    console.log('Cleaning up live session resources...');
    window.speechSynthesis.cancel();

    if (frameIntervalRef.current) {
      window.clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }

    if (mediaStreamRef.current) {
      mediaStreamRef.current.getTracks().forEach(track => track.stop());
      mediaStreamRef.current = null;
    }

    if (sessionPromiseRef.current) {
        sessionPromiseRef.current.then(session => {
            session.close();
        }).catch(() => {});
        sessionPromiseRef.current = null;
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    outputAudioContextRef.current?.close().catch(() => {});
    outputAudioContextRef.current = null;
    audioSourcesRef.current.forEach(source => { try { source.stop(); } catch(e) {} });
    audioSourcesRef.current.clear();
    nextStartTimeRef.current = 0;

    setStatus('idle');
    setUserTranscript('');
    setModelTranscript('');
  }, []);

  const handleClose = () => {
      cleanup();
      onClose();
  };

  const speakGreeting = useCallback((userName: string, lang: LanguageCode) => {
    const greetingText = TRANSLATIONS.liveSessionGreeting[lang].replace('{name}', userName);
    const utterance = new SpeechSynthesisUtterance(greetingText);
    utterance.lang = lang;
    const voices = window.speechSynthesis.getVoices();
    const selectedVoice = voices.find(v => v.lang.startsWith(lang) && v.name.includes('Google')) || voices.find(v => v.lang.startsWith(lang));
    if (selectedVoice) utterance.voice = selectedVoice;
    window.speechSynthesis.speak(utterance);
  }, []);

  useEffect(() => {
    if (isOpen) {
      startSession();
    } else {
      cleanup();
    }
    return () => cleanup();
  }, [isOpen]);

  const startSession = async () => {
    if (status !== 'idle') return;

    setStatus('connecting');
    outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

    try {
      const weatherData = analyticsService.getCurrentWeather(location);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      mediaStreamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: getLiveSystemInstruction(user.name, location, language, weatherData),
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } }
          }
        },
        callbacks: {
          onopen: () => {
            console.log('Session opened.');
            setStatus('connected');
            speakGreeting(user.name, language);

            const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
                const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
                const l = inputData.length;
                const int16 = new Int16Array(l);
                for (let i = 0; i < l; i++) int16[i] = inputData[i] * 32768;

                const pcmBlob: GenAI_Blob = {
                    data: encode(new Uint8Array(int16.buffer)),
                    mimeType: 'audio/pcm;rate=16000',
                };
                sessionPromise.then(session => {
                    session.sendRealtimeInput({ media: pcmBlob });
                }).catch(() => {});
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);

            if (videoRef.current && canvasRef.current) {
              const videoEl = videoRef.current;
              const canvasEl = canvasRef.current;
              const ctx = canvasEl.getContext('2d');

              frameIntervalRef.current = window.setInterval(async () => {
                  if (!ctx || !mediaStreamRef.current || videoEl.paused || videoEl.ended) return;

                  if (videoEl.videoWidth > 0 && videoEl.videoHeight > 0) {
                      canvasEl.width = videoEl.videoWidth;
                      canvasEl.height = videoEl.videoHeight;
                      ctx.drawImage(videoEl, 0, 0, videoEl.videoWidth, videoEl.videoHeight);

                      const blob = await new Promise<Blob | null>(resolve => canvasEl.toBlob(resolve, 'image/jpeg', JPEG_QUALITY));
                      if (blob) {
                          const base64Data = await blobToBase64(blob);
                          sessionPromise.then(session => {
                              session.sendRealtimeInput({
                                  media: { data: base64Data, mimeType: 'image/jpeg' }
                              });
                          }).catch(() => {});
                      }
                  }
              }, 1000 / FRAME_RATE);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.outputTranscription) {
              setModelTranscript(prev => prev + message.serverContent!.outputTranscription.text);
            }
            if (message.serverContent?.inputTranscription) {
              setUserTranscript(prev => prev + message.serverContent!.inputTranscription.text);
            }
            if (message.serverContent?.turnComplete) {
              setUserTranscript('');
              setModelTranscript('');
            }

            const base64EncodedAudioString = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64EncodedAudioString && outputAudioContextRef.current) {
                const ctx = outputAudioContextRef.current;
                const nextStartTime = Math.max(nextStartTimeRef.current, ctx.currentTime);
                nextStartTimeRef.current = nextStartTime;

                const audioBuffer = await decodeAudioData(decode(base64EncodedAudioString), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(ctx.destination);

                source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
                source.start(nextStartTime);
                nextStartTimeRef.current = nextStartTime + audioBuffer.duration;
                audioSourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
                audioSourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
                audioSourcesRef.current.clear();
                nextStartTimeRef.current = 0;
            }
          },
          onerror: (e: ErrorEvent) => {
            console.error('Session error:', e);
            setStatus('error');
          },
          onclose: (e: CloseEvent) => {
            console.log('Session closed.', e.reason);
            if (mediaStreamRef.current && status === 'connected') setStatus('error');
          },
        },
      });

      sessionPromiseRef.current = sessionPromise;

    } catch (error) {
      console.error('Failed to start live session:', error);
      setStatus('error');
      cleanup();
    }
  };

  return (
    <>
      {isOpen && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-sm" onClick={handleClose}>
          <div className="bg-white dark:bg-[#0D1117] rounded-2xl w-full max-w-4xl h-[90vh] shadow-2xl flex flex-col overflow-hidden border border-gray-200 dark:border-gray-700" onClick={(e) => e.stopPropagation()}>
            <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center">
                <h2 className="text-lg font-bold text-gray-800 dark:text-gray-100">{TRANSLATIONS.liveSession[language]}</h2>
                <button onClick={handleClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 text-2xl font-bold">&times;</button>
            </div>

            <div className="flex-1 relative bg-black">
                <video ref={videoRef} className="w-full h-full object-cover" autoPlay playsInline muted />
                <canvas ref={canvasRef} className="hidden" />
                <div className="absolute bottom-4 left-4 right-4 bg-black/50 p-3 rounded-lg text-white text-sm backdrop-blur-md">
                    <div className="flex items-start gap-3">
                        <div className="flex-shrink-0 w-8 h-8 rounded-full bg-gray-500 flex items-center justify-center"><UserIcon /></div>
                        <p className="flex-1 min-h-[1.25rem]">{userTranscript}</p>
                    </div>
                    <div className="flex items-start gap-3 mt-2">
                        <div className="flex-shrink-0 w-8 h-8 rounded-full bg-green-500 flex items-center justify-center"><BotIcon /></div>
                        <p className="flex-1 min-h-[1.25rem] font-medium">{modelTranscript}</p>
                    </div>
                </div>

                {status === 'connecting' && (
                    <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center text-white">
                        <div className="w-8 h-8 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
                        <p className="mt-4">Connecting to AI Field Partner...</p>
                    </div>
                )}
                 {status === 'error' && (
                    <div className="absolute inset-0 bg-red-900/80 flex flex-col items-center justify-center text-white p-4">
                        <p className="font-semibold">Connection Error</p>
                        <p className="text-sm text-center mt-2">Could not establish a live session. Please ensure your browser supports the Live API and permissions are granted.</p>
                        <button onClick={handleClose} className="mt-4 px-4 py-2 bg-white text-red-800 rounded-lg text-sm">Close</button>
                    </div>
                )}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default LiveAnalysisModal;

