      mediaStreamRef.current = null;
    }

    if (sessionPromiseRef.current) {
        sessionPromiseRef.current.then(session => {
            session.close();
        }).catch(() => {});
        sessionPromiseRef.current = null;
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    outputAudioContextRef.current?.close().catch(() => {});
    outputAudioContextRef.current = null;
    audioSourcesRef.current.forEach(source => { try { source.stop(); } catch(e) {} });
    audioSourcesRef.current.clear();
    nextStartTimeRef.current = 0;

    setStatus('idle');
    setUserTranscript('');
    setModelTranscript('');
  }, []);

  const handleClose = () => {
      cleanup();
      onClose();
  };

  const speakGreeting = useCallback((userName: string, lang: LanguageCode) => {
    const greetingText = TRANSLATIONS.liveSessionGreeting[lang].replace('{name}', userName);
    const utterance = new SpeechSynthesisUtterance(greetingText);
    utterance.lang = lang;
    const voices = window.speechSynthesis.getVoices();
    const selectedVoice = voices.find(v => v.lang.startsWith(lang) && v.name.includes('Google')) || voices.find(v => v.lang.startsWith(lang));
    if (selectedVoice) utterance.voice = selectedVoice;
    window.speechSynthesis.speak(utterance);
  }, []);

  useEffect(() => {
    if (isOpen) {
      startSession();
    } else {
      cleanup();
    }
    return () => cleanup();
  }, [isOpen]);

  const startSession = async () => {
    if (status !== 'idle') return;

    setStatus('connecting');
    outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

    try {
      const weatherData = analyticsService.getCurrentWeather(location);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      mediaStreamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: getLiveSystemInstruction(user.name, location, language, weatherData),
