// Optimized frame settings for high-speed multimodal recognition
const FRAME_RATE = 2; // Sent 2 frames per second to prevent connection lag while maintaining context
const JPEG_QUALITY = 0.4;

const getLiveSystemInstruction = (userName: string, location: string, language: LanguageCode, weather: CurrentWeather | null): string => {
    const langName = LANGUAGES.find(l => l.code === language)?.name || 'English';
    const weatherContext = weather
        ? `\n**WEATHER CONTEXT (CRITICAL):** ${weather.condition} at ${weather.temp}, ${weather.humidity}% humidity. Use this for pest/disease risk assessment.`
        : '';

    return `You are Agri-Intel Live, a state-of-the-art agricultural vision partner. You are in a real-time video session with ${userName}.

**CRITICAL: OPERATIONAL GUIDELINES**
1. **LIVE VISION FIRST:** You are receiving a constant stream of images. When the user speaks, IMMEDIATELY look at the most recent frame. 
2. **ACKNOWLEDGE WHAT YOU SEE:** Do not say "I cannot see". Look for plants, leaves, stems, or insects. Even if blurry, describe what is most likely visible.
3. **DESCRIBE NOW:** Your task is to provide instantaneous spoken feedback. Be concise.
4. **LANGUAGE:** You MUST speak ONLY in ${langName}.
5. **FIELD PARTNER PERSONA:** Be conversational. Address the user by name, ${userName}.
6. **AGRICULTURAL SCOPE:** Focus strictly on crop health, pests, diseases, and management.

${weatherContext}

**Developed by students from St. John College of Engineering and Management.**`;
}

const LiveAnalysisModal: React.FC<LiveAnalysisModalProps> = ({ isOpen, onClose, language, location, user }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const frameIntervalRef = useRef<number | null>(null);

  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');

  const sessionPromiseRef = useRef<any>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const cleanup = useCallback(() => {
    console.debug('Cleaning up resources...');
    window.speechSynthesis.cancel();
    if (frameIntervalRef.current) window.clearInterval(frameIntervalRef.current);
    if (mediaStreamRef.current) mediaStreamRef.current.getTracks().forEach(track => track.stop());
    if (sessionPromiseRef.current) sessionPromiseRef.current.then((s: any) => s.close()).catch(() => {});
    if (outputAudioContextRef.current) outputAudioContextRef.current.close().catch(() => {});
    audioSourcesRef.current.forEach(source => { try { source.stop(); } catch(e) {} });
    audioSourcesRef.current.clear();

    frameIntervalRef.current = null;
    mediaStreamRef.current = null;
    sessionPromiseRef.current = null;
    outputAudioContextRef.current = null;
    nextStartTimeRef.current = 0;
    setStatus('idle');
  }, []);

  const handleClose = () => { cleanup(); onClose(); };

  useEffect(() => {
    if (isOpen) startSession();
    else cleanup();
    return () => cleanup();
  }, [isOpen]);

  const startSession = async () => {
    if (status !== 'idle') return;
    setStatus('connecting');
    setErrorMessage('');

    // Native PCM audio context at 24kHz
    outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      mediaStreamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          // Transcriptions disabled to avoid "Operation not supported" errors and reduce latency
          systemInstruction: getLiveSystemInstruction(user.name, location, language, analyticsService.getCurrentWeather(location)),
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } }
          }
        },
        callbacks: {
          onopen: () => {
            console.log('Gemini Live session connected.');
            setStatus('connected');

            // Microphone streaming
            const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
                const inputData = e.inputBuffer.getChannelData(0);
                const int16 = new Int16Array(inputData.length);
                for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;

                const pcmBlob: GenAI_Blob = {
                    data: encode(new Uint8Array(int16.buffer)),
                    mimeType: 'audio/pcm;rate=16000',
                };
                sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob })).catch(() => {});
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);

            // Video frame streaming
            if (videoRef.current && canvasRef.current) {
              const videoEl = videoRef.current;
              const canvasEl = canvasRef.current;
              const ctx = canvasEl.getContext('2d');

              frameIntervalRef.current = window.setInterval(async () => {
                  if (!ctx || !mediaStreamRef.current || videoEl.paused || videoEl.ended) return;
                  if (videoEl.videoWidth > 0) {
                      canvasEl.width = videoEl.videoWidth;
                      canvasEl.height = videoEl.videoHeight;
                      ctx.drawImage(videoEl, 0, 0, videoEl.videoWidth, videoEl.videoHeight);
                      const blob = await new Promise<Blob | null>(resolve => canvasEl.toBlob(resolve, 'image/jpeg', JPEG_QUALITY));
                      if (blob) {
                          const base64Data = await blobToBase64(blob);
                          sessionPromise.then(s => s.sendRealtimeInput({
                              media: { data: base64Data, mimeType: 'image/jpeg' }
                          })).catch(() => {});
                      }
                  }
              }, 1000 / FRAME_RATE);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio && outputAudioContextRef.current) {
                const ctx = outputAudioContextRef.current;
                const nextStartTime = Math.max(nextStartTimeRef.current, ctx.currentTime);
                const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);

                const source = ctx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(ctx.destination);
                source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
                source.start(nextStartTime);
                nextStartTimeRef.current = nextStartTime + audioBuffer.duration;
                audioSourcesRef.add(source);
            }
            if (message.serverContent?.interrupted) {
                audioSourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
                audioSourcesRef.current.clear();
                nextStartTimeRef.current = 0;
            }
          },
          onerror: (e: any) => {
            console.error('Session error:', e);
            setStatus('error');
            setErrorMessage(e.message || 'The Live API session failed to initialize. Try checking your internet or project region settings.');
          },
          onclose: () => {
            if (status === 'connected') {
                setStatus('error');
                setErrorMessage('Connection closed unexpectedly.');
            }
          },
        },
      });
      sessionPromiseRef.current = sessionPromise;
    } catch (error: any) {
      console.error('Failed to start session:', error);
      setStatus('error');
      setErrorMessage(error.message || 'Permissions denied.');
      cleanup();
    }
  };

  return (
    <>
      {isOpen && (
        <div className="fixed inset-0 bg-black/90 z-[60] flex items-center justify-center p-0 sm:p-4 backdrop-blur-md" onClick={handleClose}>
          <div className="bg-white dark:bg-[#0D1117] w-full max-w-5xl h-full sm:h-[85vh] sm:rounded-3xl shadow-2xl flex flex-col overflow-hidden relative border border-white/10" onClick={(e) => e.stopPropagation()}>
            <video ref={videoRef} className="absolute inset-0 w-full h-full object-cover" autoPlay playsInline muted />
            <canvas ref={canvasRef} className="hidden" />

            {/* Overlay UI */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-black/40 flex flex-col justify-between p-6">
                <div className="flex justify-between items-start">
                    <div className="bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl px-4 py-2 flex items-center gap-3">
                        <div className="w-3 h-3 bg-red-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.8)]"></div>
                        <span className="text-white text-xs font-bold tracking-widest uppercase">Live Field Analysis</span>
                    </div>
                    <button onClick={handleClose} className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center text-white hover:bg-white/20 transition-all">&times;</button>
                </div>

                <div className="flex flex-col items-center gap-4">
                    {status === 'connecting' && (
                        <div className="flex flex-col items-center">
                            <div className="w-12 h-12 border-4 border-white/10 border-t-green-500 rounded-full animate-spin mb-4"></div>
                            <p className="text-white font-medium animate-pulse">Establishing Live Video Link...</p>
                        </div>
                    )}

                    {status === 'error' && (
                        <div className="bg-red-500/20 backdrop-blur-xl border border-red-500/50 rounded-3xl p-8 max-w-sm text-center">
                            <span className="text-4xl mb-4 block">⚠️</span>
                            <h3 className="text-white font-bold text-lg mb-2">Connection Error</h3>
                            <p className="text-red-200 text-sm mb-6">{errorMessage}</p>
                            <div className="flex gap-3 justify-center">
                                <button onClick={startSession} className="px-6 py-2 bg-white text-red-900 rounded-full font-bold text-sm">Retry</button>
                                <button onClick={handleClose} className="px-6 py-2 bg-white/10 text-white rounded-full font-bold text-sm">Close</button>
                            </div>
                        </div>
                    )}

                    {status === 'connected' && (
                        <div className="w-full max-w-md flex flex-col items-center text-center">
                            <div className="w-20 h-20 rounded-full bg-green-500/20 backdrop-blur-xl border border-green-500/40 flex items-center justify-center mb-6">
                                <BotIcon />
                            </div>
                            <p className="text-white/80 text-sm italic mb-2">Point your camera at the plant and speak.</p>
                            <h3 className="text-white font-bold text-xl mb-6">Agri-Intel Partner is Listening</h3>
                        </div>
                    )}
                </div>

                <div className="flex justify-center gap-8 items-center">
                   <div className="flex flex-col items-center gap-2">
                        <div className={`w-14 h-14 rounded-full flex items-center justify-center transition-all ${status === 'connected' ? 'bg-green-500 text-white shadow-[0_0_20px_rgba(34,197,94,0.4)]' : 'bg-white/10 text-white/40'}`}>
                            <BotIcon />
                        </div>
                        <span className="text-[10px] text-white/60 font-bold uppercase tracking-widest">AI Partner</span>
                   </div>
                   <div className="w-px h-12 bg-white/10"></div>
                   <div className="flex flex-col items-center gap-2">
                        <div className="w-14 h-14 rounded-full bg-white/10 flex items-center justify-center text-white border border-white/20">
                            <UserIcon />
                        </div>
                        <span className="text-[10px] text-white/60 font-bold uppercase tracking-widest">You</span>
                   </div>
                </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

