  isOpen: boolean;
  onClose: () => void;
  language: LanguageCode;
  location: string;
  user: User;
}

const FRAME_RATE = 1; // 1 FPS is stable for Gemini Vision over WebSockets
const JPEG_QUALITY = 0.5;

const getLiveSystemInstruction = (userName: string, language: LanguageCode): string => {
    const langName = LANGUAGES.find(l => l.code === language)?.name || 'English';

    return `You are Agri-Intel Live. You are in a real-time VIDEO call with ${userName}.

    CRITICAL RULES:
    1. You are receiving continuous image frames. LOOK AT THEM.
    2. Do NOT say "I cannot see anything". You ARE receiving visual data.
